 public static void main(String[] args)throws Exception{PropulsionPlacementLegacyOracle.initialize();NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);java.lang.reflect.Constructor<com.vandorlabs.tiles.DeferredTileLoad> constructor=com.vandorlabs.tiles.DeferredTileLoad.class.getDeclaredConstructor();constructor.setAccessible(true);com.vandorlabs.tiles.DeferredTileLoad deferred=constructor.newInstance();File output=new File(args[0]);output.getParentFile().mkdirs();Gson gson=new Gson();int cases=0;BlockPos base=new BlockPos(8,90,8);try(PrintWriter out=new PrintWriter(output,"UTF-8")){for(String family:new String[]{"rocket_thruster","ion_drive","plasma_vent","impulse_engine"})for(EnumFacing facing:EnumFacing.values())for(int shape=0;shape<3;shape++){Block block=Block.REGISTRY.getObject(new net.minecraft.util.ResourceLocation("vandorlabs",family));PanelPlane plane=PanelPlane.of(facing);List<BlockPos> positions=new ArrayList<>();List<TileEntityRedstoneLight> owners=new ArrayList<>();NBTTagCompound input=new NBTTagCompound();input.setBoolean("ManualOn",true);input.setBoolean("LightInitialized",true);input.setInteger("ParticleLevel",1);input.setInteger("PropulsionSideTexture",64);for(int x=0;x<2;x++)for(int y=0;y<2;y++){BlockPos pos=base.offset(plane.right,x).offset(plane.up,y);world.setBlockState(pos,block.getDefaultState().withProperty(BlockPropulsionLight.FACING,facing).withProperty(BlockPropulsionLight.POWERED,true),2);TileEntityRedstoneLight owner=(TileEntityRedstoneLight)world.getTileEntity(pos);NBTTagCompound tag=input.copy();tag.setInteger("x",pos.getX());tag.setInteger("y",pos.getY());tag.setInteger("z",pos.getZ());owner.readFromNBT(tag);owner.onLoad();positions.add(pos);owners.add(owner);}if(((BlockConnectedPropulsionLight)block).assemblyPositions(world,base).size()!=4)throw new AssertionError("Source probe is not an actual four-cell assembly");NBTTagCompound values=new NBTTagCompound();values.setInteger("propulsion_shape",shape);values.setInteger("wall_texture",7);values.setInteger("particles",3);values.setBoolean("join",false);JsonObject row=new JsonObject();row.addProperty("family",family);row.addProperty("face",facing.getIndex());row.addProperty("shape",shape);row.addProperty("input",input.toString());row.addProperty("values",values.toString());row.add("before",snapshot(world,base,positions,owners));row.addProperty("applied",ProgrammableSettings.apply(world,base,values));row.add("after",snapshot(world,base,positions,owners));out.println(gson.toJson(row));for(TileEntityRedstoneLight owner:owners)owner.invalidate();net.minecraftforge.event.world.WorldEvent.Unload event=new net.minecraftforge.event.world.WorldEvent.Unload(world);com.vandorlabs.redstone.RedstoneChannels.worldUnloaded(event);deferred.worldUnload(event);com.vandorlabs.tiles.WorldActionAuthorization.unload(event);world.clear();cases++;}}if(cases!=72)throw new AssertionError("Group coverage");byte[] raw=java.nio.file.Files.readAllBytes(output.toPath());StringBuilder hash=new StringBuilder();for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(raw))hash.append(String.format(java.util.Locale.ROOT,"%02x",b&255));if(raw.length!=143246||!hash.toString().equals("9b2293209a24fb0dc275ffb42a7c987e61a9e86904255256f43f1c95c96a2ac4"))throw new AssertionError("Released assembly copier callbacks changed: "+hash);System.out.println("Actual Source placed propulsion copier groups PASS cases="+cases+" fourFamilies/sixFaces/threeShapes/samePhysicalOwners/selectedScalarOnly");}
